import { Attributions } from '../../../shared/shared-types';
import { DisplayPackageInfos } from '../../types/types';
import { convertPackageInfoToDisplayPackageInfo } from '../../util/convert-package-info';
import { getAlphabeticalComparerForAttributions } from '../../util/get-alphabetical-comparer';

export interface SortedAndConvertedAttributions {
  sortedIds: Array<string>;
  displayPackageInfos: DisplayPackageInfos;
}

export function getSortedAndConvertedAttributions(
  attributions: Attributions,
  sortByCriticality: boolean,
): SortedAndConvertedAttributions {
  const sortedAttributionIds = Object.keys(attributions).sort(
    getAlphabeticalComparerForAttributions(attributions, sortByCriticality),
  );

  const displayPackageInfos: DisplayPackageInfos = {};
  sortedAttributionIds.forEach((attributionId) => {
    displayPackageInfos[attributionId] = convertPackageInfoToDisplayPackageInfo(
      attributions[attributionId],
      [attributionId],
    );
  });

  return {
    sortedIds: sortedAttributionIds,
    displayPackageInfos,
  };
}
